#include "PluginEditor.h"
TimberAudioProcessorEditor::TimberAudioProcessorEditor(TimberAudioProcessor&x):AudioProcessorEditor(&x),p(x){knobs={&body,&stringTone,&pick,&res,&human};const char*ids[]={"body","string","pick","res","human"};for(int i=0;i<5;++i){auto*k=knobs[i];k->setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k->setTextBoxStyle(juce::Slider::TextBoxBelow,false,80,20);addAndMakeVisible(*k);at.push_back(std::make_unique<SA>(p.apvts,ids[i],*k));}setSize(760,430);}
void TimberAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff24170e));g.setColour(juce::Colour(0xffe4bd75));g.setFont(46);g.drawText("T I M B E R",20,22,getWidth()-40,60,juce::Justification::centred);g.setFont(15);g.drawText("PHYSICAL-MODEL ACOUSTIC GUITAR",20,78,getWidth()-40,25,juce::Justification::centred);g.setFont(16);g.drawText("BODY                 STRING                 PICK                 RESONANCE                 HUMAN  0—11",40,340,getWidth()-80,30,juce::Justification::centred);}
void TimberAudioProcessorEditor::resized(){int x=45;for(auto*k:knobs){k->setBounds(x,125,120,190);x+=140;}}
